// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');

// Module-level font loading
const { fontFamily: antonFamily } = loadAnton();



export type RedFlagOverlayProps = Record<string, any>;

const RedFlagOverlay: React.FC<RedFlagOverlayProps> = ({
  backgroundColor = "#0d0d0d",
  transparentBackground = false,
  durationInSeconds = 5,
  mainText = "3",
  textColor = "#ffffff",
  textShadowColor = "#333333",
  flagColor = "#ff2a2a",
  poleColor = "#a0a0a0",
  flagScale = 1.2,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height);

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // --- Animation Logic ---

  // 1. Main Text Entrance
  const textScale = spring({
    frame,
    fps,
    config: { damping: 10, stiffness: 200, mass: 1.5 },
  });

  const textRotate = interpolate(
    spring({ frame, fps, config: { damping: 12, stiffness: 150 } }),
    [0, 1],
    [-15, 0]
  );

  const shadowDist = interpolate(textScale, [0, 1], [0, s * 0.04]);

  // 2. Red Flag Drop & Plant
  const flagDelay = 20; // Frames before flag drops
  const flagDropProgress = spring({
    frame: frame - flagDelay,
    fps,
    config: { damping: 12, stiffness: 150, mass: 1.2 },
  });

  const flagY = interpolate(flagDropProgress, [0, 1], [-height, 0]);

  const flagPlantRotate = interpolate(
    spring({
      frame: frame - flagDelay,
      fps,
      config: { damping: 8, stiffness: 200 },
    }),
    [0, 1],
    [30, 0] // Swings in dynamically
  );

  // Continuous wave after plant (deterministic using frame)
  const isPlanted = frame > flagDelay;
  const waveAngle = isPlanted ? Math.sin((frame - flagDelay) * 0.15) * 4 : 0;
  const finalFlagRotate = flagPlantRotate + waveAngle;

  // 3. Impact Effects (Lines and Flash)
  const flashOpacity = interpolate(
    frame - flagDelay,
    [0, 5, 15],
    [0, 0.4, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const lineProgress = interpolate(frame - flagDelay, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  const lineOpacity = interpolate(lineProgress, [0, 0.1, 1], [0, 1, 0]);
  const lineScale = interpolate(lineProgress, [0, 1], [0.4, 1.2]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        overflow: "hidden",
      }}
    >
      {/* Action Burst Lines (Background) */}
      {frame >= flagDelay && lineProgress < 1 && (
        <AbsoluteFill
          style={{
            justifyContent: "center",
            alignItems: "center",
            opacity: lineOpacity,
            zIndex: 1,
          }}
        >
          {Array.from({ length: 12 }).map((_, i) => {
            const angle = (i * 360) / 12;
            return (
              <div
                key={i}
                style={{
                  position: "absolute",
                  width: s * 0.015,
                  height: s * 0.4,
                  backgroundColor: flagColor,
                  transform: `rotate(${angle}deg) translateY(-${
                    s * 0.4 * lineScale
                  }px)`,
                  borderRadius: s * 0.01,
                  transition: "none",
                }}
              />
            );
          })}
        </AbsoluteFill>
      )}

      {/* Main Large Text */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
        }}
      >
        <div
          style={{
            fontFamily: antonFamily,
            fontSize: s * 0.7,
            lineHeight: 1,
            color: textColor,
            textShadow: `${shadowDist}px ${shadowDist}px 0px ${textShadowColor}`,
            transform: `scale(${textScale}) rotate(${textRotate}deg)`,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transition: "none",
          }}
        >
          {mainText}
        </div>
      </AbsoluteFill>

      {/* Red Flag Overlay Graphic */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          pointerEvents: "none",
          zIndex: 20,
        }}
      >
        <div
          style={{
            width: 200 * flagScale,
            height: 300 * flagScale,
            // Offset slightly right and up so it visually plants next to the number
            transform: `translate(${s * 0.15}px, -${
              s * 0.05
            }px) translateY(${flagY}px) rotate(${finalFlagRotate}deg)`,
            transformOrigin: `${28 * flagScale}px ${280 * flagScale}px`,
            transition: "none",
          }}
        >
          <svg
            width="100%"
            height="100%"
            viewBox="0 0 200 300"
            style={{
              overflow: "visible",
              filter: "drop-shadow(8px 8px 12px rgba(0,0,0,0.6))",
            }}
          >
            {/* Pole */}
            <rect
              x="20"
              y="20"
              width="16"
              height="260"
              rx="8"
              fill={poleColor}
            />
            {/* Waving Flag Cloth Path */}
            <path
              d="M 36 30 C 80 10, 130 50, 190 30 L 190 120 C 130 140, 80 100, 36 120 Z"
              fill={flagColor}
            />
          </svg>
        </div>
      </AbsoluteFill>

      {/* Impact Flash Overlay */}
      {flashOpacity > 0 && (
        <AbsoluteFill
          style={{
            backgroundColor: "white",
            opacity: flashOpacity,
            zIndex: 30,
            pointerEvents: "none",
            transition: "none",
          }}
        />
      )}
    </AbsoluteFill>
  );
};

export default RedFlagOverlay;